import base64,html,json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from addon.core import VERSION
out=Path(sys.argv[1]).resolve();out.mkdir(parents=True,exist_ok=True)
def image(name):return 'data:image/png;base64,'+base64.b64encode((out/name).read_bytes()).decode()
receipt=json.loads((out/'Package_Verification.json').read_text())
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workshop · Start with one source</title><style>
:root{color-scheme:dark;--bg:#101918;--panel:#1a2723;--ink:#f0ece0;--muted:#afbbb0;--line:#354238;--accent:#c9d9ad;--gold:#d6ba78}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:16px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}main{max-width:1120px;padding:55px 38px 60px;margin:auto}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:20px}.brand{font:27px Georgia,serif}.brand:before{content:"W";display:inline-grid;place-items:center;font-size:19px;width:39px;height:39px;border:1px solid var(--gold);border-radius:50%;color:var(--gold);margin-right:13px}.tag{font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:var(--muted)}h1{font:54px/1.08 Georgia,serif;letter-spacing:-1.4px;margin:38px 0 17px;max-width:780px}h2{font:31px/1.3 Georgia,serif;margin:42px 0 14px}h3{font-size:17px;margin:7px 0}p{margin:12px 0;color:var(--muted)}strong{color:var(--ink);font-weight:600}.lead{font-size:19px;max-width:730px}a{color:var(--accent);text-underline-offset:4px}button,a.button{border:1px solid transparent;display:inline-flex;align-items:center;justify-content:center;border-radius:11px;font:600 14px/1.4 system-ui;padding:14px 20px;background:var(--accent);color:#203327;text-decoration:none}a.secondary{border:1px solid var(--line);background:transparent;color:var(--ink)}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}figure{margin:26px 0}figure img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:16px}figcaption{font-size:12px;color:var(--muted);margin-top:10px}.note{border-left:3px solid var(--gold);padding:14px 19px;background:var(--panel);border-radius:0 10px 10px 0;font-size:14px;margin:25px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.step{padding:23px;border:1px solid var(--line);border-radius:15px;background:var(--panel)}.number{font-size:11px;letter-spacing:2px;color:var(--gold)}.step p{font-size:14px}.workflow{display:grid;grid-template-columns:1fr 1fr;gap:26px}table{border-collapse:collapse;width:100%;font-size:14px;margin:24px 0}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:1px}th,td{padding:13px 9px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:600;width:25%}code{font:13px ui-monospace,monospace;background:#22302a;border-radius:4px;padding:3px 5px;overflow-wrap:anywhere}details{padding:14px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer;font-weight:600}details p{font-size:14px}footer{border-top:1px solid var(--line);margin-top:42px;padding-top:22px;font-size:12px;color:var(--muted)}:focus-visible{outline:2px solid var(--gold);outline-offset:4px}@media(max-width:700px){main{padding:25px 19px 40px}h1{font-size:40px}h2{font-size:27px}.grid,.workflow{grid-template-columns:1fr;gap:12px}header{align-items:start;gap:15px}.tag{text-align:right;font-size:10px}.step{padding:19px}th,td{padding:11px 5px}.lead{font-size:17px}}
</style></head><body><main><header><div class="brand">workshop</div><div class="tag">Living Library &amp; Card Studio<br>VERSION_TOKEN · desktop Anki</div></header><h1>A place for the things<br>you want to know.</h1><p class="lead">Bring the source. Shape the right cards. Keep the context. Workshop connects a living library to a working card studio and a practical repair queue.</p><div class="actions"><a class="button" href="Workshop_VERSION_TOKEN.ankiaddon">Install the complete add-on</a><a class="button secondary" href="Workshop_Source_VERSION_TOKEN.zip">Source, tests &amp; documentation</a></div><div class="note"><strong>Native-acceptance candidate.</strong> The packaged interface and Python workflows have been tested, but no real Windows Anki/Qt process ran here. Use a backed-up, unsynced test profile first. The installer starts with your own empty library; it does not import the sample projects in these screenshots.</div><figure><img src="IMAGE_LIBRARY" alt="The actual Workshop Living Library, showing six original book bindings and sample source projects"><figcaption>Actual packaged interface with clearly marked sample data. This is not a mockup or a screenshot of an installed Windows Anki instance.</figcaption></figure><h2>Open the workshop.</h2><div class="grid"><section class="step"><div class="number">01 / INSTALL</div><h3>A separate add-on.</h3><p>In Anki, choose <strong>Tools → Add-ons → Install from file…</strong> and select <code>Workshop_VERSION_TOKEN.ankiaddon</code>. Keep the extension unchanged. Do not unzip it.</p></section><section class="step"><div class="number">02 / RESTART</div><h3>Keep your companions.</h3><p>Restart Anki. Keep Atelier and Exam Sprout installed. Workshop uses its own package and data folder; it does not replace their files, reviewer, or scheduler.</p></section><section class="step"><div class="number">03 / ENTER</div><h3>Bind your first project.</h3><p>Choose <strong>Tools → Workshop → Open Living Library</strong>, use the Workshop navigation entry, or press <strong>Ctrl+Alt+W</strong>. Name a project and choose its binding.</p></section></div><h2>One source, all the way through.</h2><div class="workflow"><section><h3>Collect and understand.</h3><p>Import a PDF, image, text, or document, or paste a source passage. Open it in Card Studio. Select the support for your question and choose <strong>Use selected passage</strong>. The citation keeps the edition, page and original wording.</p><p>Use <strong>Find existing cards</strong> before creating another note. Similar wording is a clue to inspect, not proof that two cards test the same idea.</p></section><section><h3>Shape and approve.</h3><p>Write a precise question, cloze, comparison, sequence, image question or application prompt. Add explanation, destination and tags. Save a local draft, preview the card, then <strong>Review &amp; add</strong>.</p><p>The approval screen shows the actual proposed notes, potential duplicates, field mapping, source support and planning assumptions. Nothing is marked learned by creating it.</p></section></div><figure><img src="IMAGE_STUDIO" alt="Workshop Card Studio, with original source text beside a real editable card draft"><figcaption>Text selection, draft editing, preview, source provenance and native note approval are connected through the production Python request dispatcher.</figcaption></figure><h2>Keep good cards good.</h2><table><thead><tr><th>Surface</th><th>What it does</th></tr></thead><tbody><tr><td>Improve</td><td>Mark a card <strong>Needs attention</strong> from normal review, without opening a new panel. Inspect it later, compare before and after, apply an approved correction, split an overloaded question, or compare confusing concepts.</td></tr><tr><td>Source editions</td><td>Import a revision, inspect changed passages, and queue affected linked notes. Source changes never silently rewrite your cards.</td></tr><tr><td>Media</td><td>Inspect existing images/audio and their actual note references. Reuse material additively. There is no global replacement or background media deletion.</td></tr><tr><td>Living Library</td><td>Six finished bindings, a dimensional shelf, list view, archive and meaningful preparation milestones. A prepared book means its cards are prepared, not that the subject is mastered.</td></tr><tr><td>Native integrations</td><td>Use Anki’s original Add, Browse, Preview, Sync and image-occlusion editor. Sprout receives an exact note-filter clipboard handoff, with covering decks selected in Sprout. Specialist audio/controllers/shared decks remain with their tools.</td></tr><tr><td>Optional assistance</td><td>Provide a compatible chat/embedding endpoint. Approve exactly which text is sent. Returned cards are unapproved drafts; semantic matching reranks up to 30 visible candidates. No provider/key/account is supplied or required for core features.</td></tr></tbody></table><figure><img src="IMAGE_IMPROVE" alt="Workshop Improve workspace with a repair queue, source-aware note inspection and technical checks"><figcaption>Repair suggestions are not factual diagnoses. Exact field changes and native-card consequences remain inspectable before approval.</figcaption></figure><h2>Your collection stays yours.</h2><details open><summary>Where things are saved</summary><p>Projects, source editions, drafts and repair links are local to <code>&lt;Anki profile&gt;/workshop/</code>. Export the local library separately. This private database is not synchronized by AnkiWeb. Approved notes and their copied media are ordinary Anki collection content.</p></details><details><summary>PDFs, images and document fidelity</summary><p>PDF text extraction is bundled. Exact PDF page rendering/cropping requires the optional Qt PDF module; otherwise extracted text and Open original remain available. DOCX/PPTX import extracts text, not a page-perfect visual layout. Export those documents to PDF for visual work. No OCR or automatic factual certification occurs.</p></details><details><summary>Approval, undo and history</summary><p>Card creation and editing use native collection operations. Workshop Undo is limited to its own latest operation and refuses to undo someone else’s intervening change. Media files/source copies are not removed by native note undo. Splitting creates new unlearned drafts and does not transfer the original card’s maturity. Original IDs/history are preserved for ordinary wording repairs.</p></details><details><summary>Privacy and optional AI</summary><p>AI is disabled initially. Keys are kept in memory for the current profile session only. Per-request content consent is separate from allowing a remote endpoint. The approved text may be subject to your selected provider’s policies or charges; no live provider was exercised in these tests.</p></details><details><summary>Native acceptance and current compatibility</summary><p>No native Windows Anki 25.09.5 installation, image-occlusion editor, actual Qt PDF renderer, sync or full installed-add-on combination has been exercised here. The supplied older Atelier front end was tested, not the user’s newer 0.7.1. The native checklist in the source archive is the public-release gate, not a list of already completed tests.</p></details><div class="note"><strong>Exact-installer verification:</strong> PYTHON_COUNT Python tests and BROWSER_COUNT browser checks passed, with no uncaught browser errors. Production code/assets were loaded from a clean installer extraction. Python tests use explicit Anki/Qt doubles and real local SQLite fixtures; browser tests exercise the actual UI and Python dispatcher. These do not certify native Windows behavior.</div><div class="actions"><a href="Workshop_VERSION_TOKEN_Test_Report.md">Verification report</a><a href="Workshop_Feature_Coverage.md">Feature coverage and boundaries</a><a href="Workshop_Privacy.md">Privacy details</a></div><footer>Workshop · Daedalus Works<br>Original artwork, icons and code. pypdf’s license is retained in the installer. No AnkiWeb upload or public install code has been created.</footer></main></body></html>'''
for a,b in {'VERSION_TOKEN':VERSION,'IMAGE_LIBRARY':image('Workshop_Living_Library.png'),'IMAGE_STUDIO':image('Workshop_Card_Studio.png'),'IMAGE_IMPROVE':image('Workshop_Improve.png'),'PYTHON_COUNT':str(receipt['python']['tests']),'BROWSER_COUNT':str(receipt['browser_total'])}.items():page=page.replace(a,b)
